function hmParseDate(s){
  var m=String(s).trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(!m) return null;
  var y=+m[1], mo=+m[2], d=+m[3];
  if(mo<1||mo>12||d<1||d>31) return null;
  var dt=new Date(Date.UTC(y, mo-1, d));
  if(dt.getUTCFullYear()!==y || dt.getUTCMonth()!==mo-1 || dt.getUTCDate()!==d) return null;
  return dt;
}
function hmFmtDate(dt){
  function p(x){ return (x<10?'0':'')+x; }
  return dt.getUTCFullYear()+'-'+p(dt.getUTCMonth()+1)+'-'+p(dt.getUTCDate());
}
function hmParse(text){
  var lines=String(text||'').split(/\n+/), map={}, bad=0, count=0;
  for(var i=0;i<lines.length;i++){
    var l=lines[i].trim();
    if(!l || l.charAt(0)==='#') continue;
    var parts=l.split(/[\s,\t]+/);
    var dt=hmParseDate(parts[0]);
    if(!dt){ bad++; continue; }
    var v = parts.length>1 ? parseFloat(parts[1]) : 1;
    if(isNaN(v)){ bad++; continue; }
    var key=hmFmtDate(dt);
    map[key]=(map[key]||0)+v;
    count++;
  }
  if(!count) return { error:'未解析到有效数据（格式：2026-07-30 3）', bad:bad };
  return { error:null, map:map, bad:bad, count:count };
}
function hmDayIndex(dt){ return Math.floor(dt.getTime()/86400000); }
function hmRange(map){
  var keys=Object.keys(map).sort();
  return { first:keys[0], last:keys[keys.length-1], days:keys.length };
}
function hmGrid(map, startStr, endStr){
  var start=hmParseDate(startStr), end=hmParseDate(endStr);
  if(!start || !end || end<start) return { error:'起止日期无效' };
  var s=new Date(start.getTime());
  s.setUTCDate(s.getUTCDate() - s.getUTCDay());
  var weeks=[], cur=new Date(s.getTime()), guard=0;
  while(cur<=end && guard<400){
    var col=[];
    for(var d=0; d<7; d++){
      var key=hmFmtDate(cur);
      var inRange = cur>=start && cur<=end;
      col.push({ date:key, value: inRange ? (map[key]||0) : null, dow:d });
      cur=new Date(cur.getTime()+86400000);
    }
    weeks.push(col); guard++;
  }
  return { error:null, weeks:weeks, start:hmFmtDate(start), end:hmFmtDate(end) };
}
function hmLevels(map, buckets){
  buckets = buckets || 4;
  var vals=[];
  for(var k in map) if(map[k]>0) vals.push(map[k]);
  if(!vals.length) return [];
  vals.sort(function(a,b){ return a-b; });
  var cuts=[];
  for(var i=1;i<=buckets;i++){
    var idx=Math.min(vals.length-1, Math.ceil(vals.length*i/buckets)-1);
    cuts.push(vals[idx]);
  }
  return cuts;
}
function hmLevelOf(v, cuts){
  if(v===null || v===undefined) return -1;
  if(v<=0) return 0;
  for(var i=0;i<cuts.length;i++) if(v<=cuts[i]) return i+1;
  return cuts.length;
}
function hmStreak(map, startStr, endStr){
  var start=hmParseDate(startStr), end=hmParseDate(endStr);
  if(!start || !end) return { best:0, current:0, active:0 };
  var cur=new Date(start.getTime()), run=0, best=0, active=0, total=0, guard=0;
  while(cur<=end && guard<3000){
    var v=map[hmFmtDate(cur)]||0;
    if(v>0){ run++; total++; if(run>best) best=run; } else run=0;
    cur=new Date(cur.getTime()+86400000); guard++;
  }
  active=run;
  return { best:best, current:active, active:total };
}
function hmStats(map){
  var vals=[], sum=0, mx=0, mxKey=null;
  for(var k in map){ vals.push(map[k]); sum+=map[k]; if(map[k]>mx){ mx=map[k]; mxKey=k; } }
  if(!vals.length) return { total:0, days:0, avg:0, max:0, maxDate:null };
  return { total:Math.round(sum*100)/100, days:vals.length,
           avg:Math.round(sum/vals.length*100)/100, max:mx, maxDate:mxKey };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { hmParseDate:hmParseDate, hmFmtDate:hmFmtDate, hmParse:hmParse, hmRange:hmRange,
    hmGrid:hmGrid, hmLevels:hmLevels, hmLevelOf:hmLevelOf, hmStreak:hmStreak, hmStats:hmStats };
}
if (typeof window !== 'undefined') {
  window.HeatmapForgePure = { hmParseDate:hmParseDate, hmFmtDate:hmFmtDate, hmParse:hmParse, hmRange:hmRange,
    hmGrid:hmGrid, hmLevels:hmLevels, hmLevelOf:hmLevelOf, hmStreak:hmStreak, hmStats:hmStats };
}
